//
// Example:
//
//	request := &plaid.SandboxTransferTestClockAdvanceRequest{
//	    TestClockID: "test_clock_id",
//	    NewVirtualTime: plaid.MustParseDateTime(
//	        "2024-01-15T09:30:00Z",
