// Use the `/sandbox/transfer/test_clock/list` endpoint to see a list of all your test clocks in the Sandbox environment, by descending `virtual_time`. Results are paginated; use the `count` and `offset` query parameters to retrieve the desired test clocks.
//
// Example:
//
//	request := &plaid.SandboxTransferTestClockListRequest{}
//	client.Sandbox.ListTransferTestClocks(
//	    context.TODO(),
//	    request,
//	)
func (c *Client) ListTransferTestClocks(
	ctx context.Context,
	request *plaid.SandboxTransferTestClockListRequest,
	opts ...option.RequestOption,
) (*core.Page[*int, *plaid.TransferTestClock, *plaid.SandboxTransferTestClockListResponse], error) {
	options := core.NewRequestOptions(opts...)
	baseURL := internal.ResolveBaseURL(
		options.BaseURL,
		c.baseURL,
		"https://production.plaid.com",
	)
	endpointURL := baseURL + "/sandbox/transfer/test_clock/list"
	headers := internal.MergeHeaders(
		c.options.ToHeader(),
		options.ToHeader(),
	)
	headers.Add("Content-Type", "application/json")
	prepareCall := func(pageRequest *core.PageRequest[*int]) *internal.CallParams {
		nextRequest := *request
		nextRequest.Offset = pageRequest.Cursor
		nextURL := endpointURL
		return &internal.CallParams{
			URL:             nextURL,
			Method:          http.MethodPost,
			Headers:         headers,
			MaxAttempts:     options.MaxAttempts,
			DisableRetries:  options.DisableRetries,
			BodyProperties:  options.BodyProperties,
			QueryParameters: options.QueryParameters,
			Client:          options.HTTPClient,
			Request:         &nextRequest,
			Response:        pageRequest.Response,
			ErrorDecoder:    internal.NewErrorDecoder(plaid.ErrorCodes),
		}
	}
	next := 0
	if request.Offset != nil {
		next = *request.Offset
	}

	readPageResponse := func(response *plaid.SandboxTransferTestClockListResponse) *core.PageResponse[*int, *plaid.TransferTestClock, *plaid.SandboxTransferTestClockListResponse] {
		results := response.GetTestClocks()
		next += int(len(results))
		return &core.PageResponse[*int, *plaid.TransferTestClock, *plaid.SandboxTransferTestClockListResponse]{
			Results:  results,
			Response: response,
			Next:     &next,
		}
	}
	pager := internal.NewOffsetPager(
		c.caller,
		prepareCall,
		readPageResponse,
	)
	return pager.GetPage(ctx, &next)
}

